function ArchivedProjects() {
  const {locale}=useUi(); const zh=locale==='zh-CN'; const [items,setItems]=useState([]); const [busy,setBusy]=useState(''); const [error,setError]=useState('')
  const refresh=useCallback(()=>api('/projects/archived').then(setItems).catch(err=>setError(err.message)),[])
  useEffect(()=>{refresh()},[refresh])
  const restore=async id=>{setBusy(id);try{await api(`/projects/${id}/restore`,{method:'POST'});await refresh();window.dispatchEvent(new Event('atoms-projects-changed'))}catch(err){setError(err.message)}finally{setBusy('')}}
  const remove=async id=>{if(!window.confirm(zh?'永久删除后无法恢复，继续吗？':'This permanently deletes the project. Continue?'))return;setBusy(id);try{await api(`/projects/${id}`,{method:'DELETE'});await refresh()}catch(err){setError(err.message)}finally{setBusy('')}}
  return <section className="archived-projects"><div className="settings-section-head"><span className="settings-icon"><Archive size={19}/></span><div><h2>{zh?'已归档项目':'Archived projects'}</h2><p>{zh?'恢复项目，或永久删除项目及其运行资源。':'Restore projects or permanently delete their data and runtime resources.'}</p></div></div>{error&&<div className="form-error">{error}</div>}{items.length?<div className="archive-list">{items.map(project=><article key={project.id}><ProjectIcon project={project}/><span><b>{project.name}</b><small>{new Date(project.archived_at).toLocaleString()}</small></span><button disabled={busy===project.id} onClick={()=>restore(project.id)}><RotateCw size={14}/>{zh?'恢复':'Restore'}</button><button className="danger" disabled={busy===project.id} onClick={()=>remove(project.id)}><Trash2 size={14}/>{zh?'删除':'Delete'}</button></article>)}</div>:<p className="archive-empty">{zh?'暂无已归档项目':'No archived projects'}</p>}</section>
}

