function DiscoverPage({ onUseTemplate }) { const {t}=useUi(); const [templates,setTemplates]=useState([]); const [filter,setFilter]=useState('All'); useEffect(()=>{api('/discover').then(setTemplates)},[]); const categories=['All',...new Set(templates.map(x=>x.category))]; const shown=filter==='All'?templates:templates.filter(x=>x.category===filter); return <PageShell eyebrow={t('starterLibrary')} title={t('discover')} description={t('discoverDesc')}><div className="discover-filters">{categories.map(item=><button key={item} className={filter===item?'active':''} onClick={()=>setFilter(item)}>{item==='All'?t('all'):item}</button>)}</div><section className="template-gallery">{shown.map(template=><article key={template.id}><div className="template-visual" style={{'--template-accent':template.accent}}><GalleryVerticalEnd size={34}/><i/><i/><i/></div><small>{template.category}</small><h2>{template.name}</h2><p>{template.description}</p><button onClick={()=>onUseTemplate(template)}>{t('useTemplate')}<ArrowUp size={15}/></button></article>)}</section></PageShell> }

function CloudPage() {
  const {t,locale,theme}=useUi(); const zh=locale==='zh-CN'; const [deployments,setDeployments]=useState([]); const [containers,setContainers]=useState([]); const [consoleState,setConsoleState]=useState(null); const [logs,setLogs]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const logsRef=useRef(null)
  const refresh=useCallback(async()=>{try{const [nextDeployments,nextContainers]=await Promise.all([api('/cloud/deployments'),api('/cloud/containers')]);setDeployments(nextDeployments);setContainers(nextContainers);setError('')}catch(err){setError(err.message)}},[])
  useEffect(()=>{refresh();const timer=setInterval(refresh,5000);return()=>clearInterval(timer)},[refresh])
  const serviceAction=async(container,action)=>{setBusy(true);try{await api(`/cloud/containers/${container.id}/action`,{method:'POST',body:JSON.stringify({action})});await refresh()}catch(err){setError(err.message)}finally{setBusy(false)}}
  const fetchLogs=useCallback(async container=>{try{setLogs((await api(`/cloud/containers/${container.id}/logs?tail=1000`)).logs)}catch(err){setLogs(err.message)}},[])
  const openLogs=container=>{setConsoleState({mode:'logs',container});setLogs('');fetchLogs(container)}
  const openTerminal=container=>setConsoleState({mode:'terminal',container})
  useEffect(()=>{if(consoleState?.mode!=='logs')return;const timer=setInterval(()=>fetchLogs(consoleState.container),1500);return()=>clearInterval(timer)},[consoleState,fetchLogs])
  useEffect(()=>{if(logsRef.current)logsRef.current.scrollTop=logsRef.current.scrollHeight},[logs])
  const offline=async projectId=>{if(!window.confirm(zh?'下线会停止并移除此项目当前的运行服务，项目数据仍会保留。继续吗？':'Take this project offline and remove its running services? Project data will be retained.'))return;setBusy(true);try{await api(`/cloud/projects/${projectId}/stack`,{method:'DELETE'});await refresh()}catch(err){setError(err.message)}finally{setBusy(false)}}
  const serviceName=role=>({frontend:zh?'网站':'Website',backend:zh?'应用服务':'Application',postgres:zh?'数据服务':'Data service',application:zh?'应用服务':'Application'})[role]||role
  const stacks=deployments.map(deployment=>({...deployment,services:containers.filter(container=>container.project_id===deployment.project_id)})); const running=containers.filter(x=>x.status==='running').length
  return <PageShell eyebrow="ATOMS CLOUD" title={t('cloudTitle')} description={zh?'查看已发布项目的运行状态、日志和终端。':'View the status, logs and terminal for published projects.'} action={<button className="secondary-btn" onClick={refresh}><RefreshCw size={16}/>{t('refresh')}</button>}>
    {error&&<div className="form-error">{error}</div>}<section className="overview-stats cloud-stats"><article><small>{zh?'项目运行栈':'Project stacks'}</small><strong>{stacks.length}</strong></article><article><small>{t('containers')}</small><strong>{containers.length}</strong></article><article><small>{t('running')}</small><strong>{running}</strong></article></section>
    <section className="stack-list">{stacks.map(stack=><article className="stack-card" key={stack.project_id}><header><span className="cloud-icon"><Cloud size={20}/></span><div><b>{stack.project_name||stack.project_id}</b><small>v{stack.metadata?.version||stack.version_number||'current'} · {stack.services.length} {zh?'个服务':'services'}</small></div><span className={`runtime-status ${stack.status}`}>{stack.status}</span>{stack.url&&<a href={stack.url} target="_blank" rel="noreferrer">{t('openApp')}<ExternalLink size={14}/></a>}<button className="offline-btn" disabled={busy} onClick={()=>offline(stack.project_id)}><Trash2 size={14}/>{zh?'一键下线':'Take offline'}</button></header><div className="stack-services">{stack.services.map(container=><div className="service-row" key={container.id}><span className={`service-icon ${container.role}`}>{container.role==='postgres'?<Database size={16}/>:container.role==='frontend'?<Monitor size={16}/>:<Code2 size={16}/>}</span><span><b>{serviceName(container.role)}</b><small>{zh?'运行实例':'Running instance'}</small></span><span className={`runtime-status ${container.status}`}>{container.health||container.status}</span><div className="service-actions"><button title={zh?'日志':'Logs'} onClick={()=>openLogs(container)}><FileDiff size={15}/></button><button title={zh?'终端':'Terminal'} disabled={container.status!=='running'} onClick={()=>openTerminal(container)}><Terminal size={15}/></button>{container.status==='running'?<button title={t('stop')} disabled={busy} onClick={()=>serviceAction(container,'stop')}><Square size={14}/></button>:<button title={t('start')} disabled={busy} onClick={()=>serviceAction(container,'start')}><Play size={14}/></button>}<button title={t('restart')} disabled={busy} onClick={()=>serviceAction(container,'restart')}><RotateCcw size={14}/></button></div></div>)}</div></article>)}{!stacks.length&&<div className="cloud-empty"><Cloud size={30}/><b>{t('noDeployments')}</b><p>{t('noDeploymentsDesc')}</p></div>}</section>
    {consoleState&&<div className="modal-backdrop cloud-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setConsoleState(null)}><section className="cloud-console"><header><div>{consoleState.mode==='logs'?<FileDiff size={19}/>:<Terminal size={19}/>}<span><b>{consoleState.mode==='logs'?(zh?'服务日志':'Service logs'):(zh?'交互终端':'Interactive terminal')}</b><small>{serviceName(consoleState.container.role)}</small></span></div><button className="icon-btn" onClick={()=>setConsoleState(null)}><X size={18}/></button></header>{consoleState.mode==='logs'?<><div className="console-tabs"><b><i className="live-dot"/>{zh?'实时日志 · 自动跟随':'Live logs · auto-follow'}</b></div><pre ref={logsRef} className="logs-output">{logs||t('noLogs')}</pre></>:<React.Suspense fallback={<div className="editor-loading"><LoaderCircle className="spin"/></div>}><TerminalConsole containerId={consoleState.container.id} theme={theme}/></React.Suspense>}</section></div>}
  </PageShell>
}

function CloudPageLegacy() {
  const {t}=useUi(); const [deployments,setDeployments]=useState([]); const [containers,setContainers]=useState([]); const [selected,setSelected]=useState(null); const [logs,setLogs]=useState(''); const [command,setCommand]=useState('["python","-c","print(\'cloud-exec-ok\')"]'); const [output,setOutput]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState('')
  const refresh=useCallback(async()=>{try{const [d,c]=await Promise.all([api('/cloud/deployments'),api('/cloud/containers')]);setDeployments(d);setContainers(c);setError('')}catch(err){setError(err.message)}},[]); useEffect(()=>{refresh();const timer=setInterval(refresh,5000);return()=>clearInterval(timer)},[refresh])
  const openLogs=async container=>{setSelected(container);setOutput('');try{setLogs((await api(`/cloud/containers/${container.id}/logs?tail=400`)).logs)}catch(err){setLogs(err.message)}}; const action=async(container,kind)=>{setBusy(true);try{await api(`/cloud/containers/${container.id}/action`,{method:'POST',body:JSON.stringify({action:kind})});await refresh()}catch(err){setError(err.message)}finally{setBusy(false)}}; const removeDeployment=async item=>{if(!window.confirm(t('removeDeploymentConfirm')))return;setBusy(true);try{await api(`/cloud/deployments/${item.id}`,{method:'DELETE'});await refresh()}catch(err){setError(err.message)}finally{setBusy(false)}}
  const execute=async()=>{setBusy(true);setOutput('');try{const argv=JSON.parse(command);if(!Array.isArray(argv))throw new Error(t('commandArray'));const result=await api(`/cloud/containers/${selected.id}/exec`,{method:'POST',body:JSON.stringify({command:argv})});setOutput(`exit ${result.exit_code}\n${result.stdout}${result.stderr}`)}catch(err){setOutput(err.message)}finally{setBusy(false)}}; const running=containers.filter(x=>x.status==='running').length
  return <PageShell eyebrow="ATOMS CLOUD" title={t('cloudTitle')} description={t('cloudDesc')} action={<button className="secondary-btn" onClick={refresh}><RefreshCw size={16}/>{t('refresh')}</button>}>
    {error&&<div className="form-error">{error}</div>}<section className="overview-stats cloud-stats"><article><small>{t('deployments')}</small><strong>{deployments.length}</strong></article><article><small>{t('containers')}</small><strong>{containers.length}</strong></article><article><small>{t('running')}</small><strong>{running}</strong></article></section>
    <div className="section-title"><h2>{t('deployments')}</h2><span>{t('dockerRuntime')}</span></div><section className="deployment-grid">{deployments.map(item=><article key={item.id}><div className="deployment-head"><span className="cloud-icon"><Cloud size={20}/></span><div><b>{item.project_name||item.project_id}</b><small>#{item.id.slice(0,8)} · {item.provider}</small></div><span className={`runtime-status ${item.status}`}>{item.status}</span></div>{item.error&&<p className="deployment-error">{item.error}</p>}<div className="deployment-meta"><span><Database size={14}/>{t('isolatedDatabase')}</span><span><Workflow size={14}/>{new Date(item.created_at).toLocaleString()}</span></div><div className="deployment-actions">{item.url&&<a href={item.url} target="_blank" rel="noreferrer">{t('openApp')}<ExternalLink size={14}/></a>}<button disabled={busy} onClick={()=>removeDeployment(item)}><Trash2 size={14}/>{t('removeDeployment')}</button></div></article>)}{!deployments.length&&<div className="cloud-empty"><Cloud size={30}/><b>{t('noDeployments')}</b><p>{t('noDeploymentsDesc')}</p></div>}</section>
    <div className="section-title"><h2>{t('containerManagement')}</h2><span>{t('managedOnly')}</span></div><section className="container-table"><div className="container-row header"><span>{t('container')}</span><span>{t('role')}</span><span>{t('image')}</span><span>{t('state')}</span><span>{t('operations')}</span></div>{containers.map(container=><div className="container-row" key={container.id}><span><b>{container.name}</b><small>{container.short_id}</small></span><span className="role-chip">{container.role}</span><code>{container.image}</code><span className={`runtime-status ${container.status}`}>{container.health||container.status}</span><span className="container-actions"><button title={t('logs')} onClick={()=>openLogs(container)}><SquareTerminal size={15}/></button>{container.status==='running'?<button title={t('stop')} disabled={busy} onClick={()=>action(container,'stop')}><Square size={14}/></button>:<button title={t('start')} disabled={busy} onClick={()=>action(container,'start')}><Play size={15}/></button>}<button title={t('restart')} disabled={busy} onClick={()=>action(container,'restart')}><RotateCcw size={15}/></button></span></div>)}</section>
    {selected&&<div className="modal-backdrop cloud-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setSelected(null)}><section className="cloud-console"><header><div><SquareTerminal size={19}/><span><b>{selected.name}</b><small>{selected.role} · {selected.short_id}</small></span></div><button className="icon-btn" onClick={()=>setSelected(null)}><X size={18}/></button></header><div className="console-tabs"><b>{t('logs')}</b><button onClick={()=>openLogs(selected)}><RefreshCw size={14}/>{t('refresh')}</button></div><pre>{logs||t('noLogs')}</pre><label>{t('execCommand')}<div><input value={command} onChange={e=>setCommand(e.target.value)}/><button className="primary-btn" disabled={busy} onClick={execute}>{t('run')}</button></div></label>{output&&<pre className="exec-output">{output}</pre>}</section></div>}
  </PageShell>
}

const workflowStages=['discovery','product','architecture','approval','implementation','verification']
function WorkflowStrip({ events,run }) {
  const {t}=useUi(); const phase=run?.state==='awaiting_approval'?'approval':run?.state==='building'?'implementation':run?.state==='testing'||run?.state==='preview_ready'?'verification':run?.state==='planning'?'product':'discovery'; const activeIndex=workflowStages.indexOf(phase)
  return <div className="workflow-strip">{workflowStages.map((stage,index)=>{const completed=events.some(e=>e.payload?.stage===stage&&e.payload?.status==='completed')||index<activeIndex||run?.state==='preview_ready'; const active=index===activeIndex&&!['preview_ready','failed'].includes(run?.state); return <div key={stage} className={`${completed?'complete':''} ${active?'active':''}`}><span>{completed?<Check size={12}/>:active?<LoaderCircle className="spin" size={12}/>:index+1}</span><small>{stage}</small></div>})}</div>
}

function PlanCard({ run,onApprove,onRevise,approving }) {
  const {t}=useUi(); const [editing,setEditing]=useState(false); const [feedback,setFeedback]=useState(''); if(!run?.plan)return null; const plan=run.plan; const architecture=plan.architecture?Object.values(plan.architecture):[]
  return <article className="plan-card"><div className="plan-head"><Avatar agent="mike"/><div><b>{t('productPlan')}</b><small>{t('preparedBy')}</small></div><span>{plan.features?.length||0} {t('features')}</span></div><p>{plan.summary}</p><div className="plan-grid"><div><small>{t('pages')}</small>{plan.pages?.map(x=><span key={x}>{x}</span>)}</div><div><small>{t('coreFeatures')}</small>{plan.features?.slice(0,6).map(x=><span key={x}>{x}</span>)}</div><div><small>{t('architecture')}</small>{architecture.map(x=><span key={x}>{x}</span>)}</div><div><small>{t('decisions')}</small>{(plan.decisions_required||[]).map(x=><span key={x}>{x}</span>)}</div></div>{run.state==='awaiting_approval'&&<>{editing&&<textarea className="revision-input" rows="3" autoFocus placeholder={t('changePlaceholder')} value={feedback} onChange={e=>setFeedback(e.target.value)}/>}<div className="approval-row"><button className="secondary-btn" onClick={()=>editing&&feedback.trim()?onRevise(feedback.trim()):setEditing(!editing)} disabled={approving}>{t('requestChanges')}</button><button className="primary-btn" onClick={onApprove} disabled={approving}>{approving?<LoaderCircle className="spin" size={17}/>:<Check size={17}/>} {t('approveBuild')}</button></div></>}</article>
}

function Conversation({ projectId,events,run,onApprove,onRevise,approving,onSend }) {
  const {t,locale}=useUi(); const zh=locale==='zh-CN'; const [message,setMessage]=useState(''); const [attachments,setAttachments]=useState([]); const [sending,setSending]=useState(false); const [attachError,setAttachError]=useState(''); const inputRef=useRef(null); const bottomRef=useRef(null)
  useEffect(()=>{bottomRef.current?.scrollIntoView({behavior:'smooth'})},[events.length,run?.state])
  const pickFiles=async event=>{setAttachError('');const picked=[...event.target.files];if(attachments.length+picked.length>5){setAttachError(zh?'最多添加 5 个附件':'Up to 5 attachments');return}for(const file of picked){if(file.size>8*1024*1024){setAttachError(`${file.name} ${zh?'超过 8MB':'is over 8MB'}`);continue}const data_url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});setAttachments(items=>[...items,{name:file.name,mime:file.type||'text/plain',data_url}])}event.target.value=''}
  const send=async event=>{event.preventDefault();if((!message.trim()&&!attachments.length)||sending)return;setSending(true);try{await onSend({content:message.trim(),attachments});setMessage('');setAttachments([])}finally{setSending(false)}}
  const token=encodeURIComponent(localStorage.getItem('atoms_token')||''); const active=['created','planning','building','testing'].includes(run?.state); const iteration=events.filter(e=>e.payload?.iteration).at(-1)?.payload?.iteration
  return <section className="conversation"><div className="react-strip"><span className={active?'active':''}><Bot size={15}/>{active?(zh?'正在构建':'Building'):(zh?'准备就绪':'Ready')}</span><small>{iteration?`${zh?'进度 ':'Progress '}${iteration}`:(zh?'理解需求 → 完成功能 → 检查结果':'Understand → Build → Check')}</small><em>{zh?'可随时追加要求':'Add requests anytime'}</em></div><div className="conversation-scroll"><div className="conversation-intro"><span className="mini-spark"><Zap size={18}/></span><div><b>{zh?'Alex · 项目助理':'Alex · project assistant'}</b><p>{zh?'会根据当前结果持续调整，直到功能可以正常使用。':'Keeps adapting to the current result until the product works.'}</p></div><Avatar agent="alex" size="xs"/></div>{events.map(event=>{if(event.type==='plan')return null; const meta=agentMeta[event.agent]||agentMeta.system; const change=event.payload?.result?.change; const attached=event.payload?.attachments||[]; return <div className={`message ${event.agent==='user'?'user-message':''}`} key={event.id}><Avatar agent={event.agent}/><div className="message-body"><div className="message-meta"><b>{meta.name}</b>{meta.role&&<span>{meta.role}</span>}<time>{new Date(event.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div><p>{event.summary}</p>{attached.length>0&&<div className="message-attachments">{attached.map(item=>item.mime.startsWith('image/')?<a key={item.id} href={`${API}/projects/${projectId}/attachments/${item.id}?token=${token}`} target="_blank"><img src={`${API}/projects/${projectId}/attachments/${item.id}?token=${token}`} alt={item.name}/><span>{item.name}</span></a>:<a key={item.id} href={`${API}/projects/${projectId}/attachments/${item.id}?token=${token}`} target="_blank"><FileText size={17}/><span>{item.name}</span></a>)}</div>}{event.type==='tool'&&<span className="tool-chip"><FileDiff size={13}/>{event.payload?.result?.path||event.payload?.tool?.replace('_',' ')}{change&&<em>+{change.added} −{change.removed}</em>}</span>}</div></div>})}{active&&<div className="thinking-row"><Avatar agent="alex"/><span><i/><i/><i/></span><small>{t('working')}</small></div>}<div ref={bottomRef}/></div><form className="composer" onSubmit={send}>{attachments.length>0&&<div className="pending-attachments">{attachments.map((item,index)=><span key={`${item.name}-${index}`}>{item.mime.startsWith('image/')?<img src={item.data_url} alt=""/>:<FileText size={15}/>}<b>{item.name}</b><button type="button" onClick={()=>setAttachments(items=>items.filter((_,i)=>i!==index))}><X size={13}/></button></span>)}</div>}{attachError&&<small className="attach-error">{attachError}</small>}<textarea rows="2" value={message} onChange={e=>setMessage(e.target.value)} placeholder={active?(zh?'追加要求，当前任务会及时调整…':'Add a request and the current task will adapt…'):t('askTeam')}/><div className="composer-bar"><div><input ref={inputRef} hidden type="file" multiple accept="image/png,image/jpeg,image/webp,image/gif,.pdf,.txt,.md,.csv,.json,.docx" onChange={pickFiles}/><button type="button" className="icon-btn" title={zh?'添加图片或文档':'Attach image or document'} onClick={()=>inputRef.current?.click()}><Paperclip size={18}/></button><span>{zh?'智能协作':'Smart collaboration'} · {run?.mode==='team'?t('teamMode'):t('engineerMode')}</span></div><button className="send-btn" disabled={(!message.trim()&&!attachments.length)||sending}>{sending?<LoaderCircle className="spin" size={17}/>:<ArrowUp size={18}/>}</button></div></form></section>
}

function makeFileTree(files) {
  const root={name:'',path:'',children:new Map(),file:false}
  files.forEach(path=>{let node=root;path.split('/').forEach((name,index,parts)=>{if(!node.children.has(name))node.children.set(name,{name,path:parts.slice(0,index+1).join('/'),children:new Map(),file:index===parts.length-1});node=node.children.get(name)})})
  return root
}

function FileTreeRows({ node,selected,onSelect,changedFiles,open,setOpen,depth=0 }) {
  return [...node.children.values()].sort((a,b)=>Number(a.file)-Number(b.file)||a.name.localeCompare(b.name)).map(child=>child.file?<button key={child.path} className={`tree-node tree-file ${selected===child.path?'active':''} ${changedFiles[child.path]?'changed':''}`} onClick={()=>onSelect(child.path)} style={{'--depth':depth}}><FileCode2 size={14}/><span>{child.name}</span>{changedFiles[child.path]&&<i/>}</button>:<React.Fragment key={child.path}><button className="tree-node tree-folder" onClick={()=>setOpen(items=>({...items,[child.path]:items[child.path]===false}))} style={{'--depth':depth}}><ChevronRight className={open[child.path]!==false?'expanded':''} size={13}/>{open[child.path]!==false?<FolderOpen size={15}/>:<Folder size={15}/>}<span>{child.name}</span></button>{open[child.path]!==false&&<FileTreeRows node={child} selected={selected} onSelect={onSelect} changedFiles={changedFiles} open={open} setOpen={setOpen} depth={depth+1}/>}</React.Fragment>)
}

function FileBrowser({ projectId,files,changedFiles,fileRevision,onManualSave,readOnly }) {
  const {t}=useUi(); const [selected,setSelected]=useState(files[0]||''); const [content,setContent]=useState(''); const [original,setOriginal]=useState(''); const [filter,setFilter]=useState(''); const [open,setOpen]=useState({}); const [saving,setSaving]=useState(false); const [saveResult,setSaveResult]=useState(null)
  const shown=files.filter(file=>file.toLowerCase().includes(filter.toLowerCase())); const tree=useMemo(()=>makeFileTree(shown),[shown]); const selectedRevision=changedFiles[selected]?.eventId||fileRevision
  const load=useCallback(async path=>{if(!path)return;const data=await api(`/projects/${projectId}/file?path=${encodeURIComponent(path)}`);setContent(data.content);setOriginal(data.content);setSaveResult(null)},[projectId])
  useEffect(()=>{if(!files.includes(selected))setSelected(files[0]||'')},[files,selected]); useEffect(()=>{load(selected).catch(()=>{})},[selected,selectedRevision,load])
  const save=async nextContent=>{const value=typeof nextContent==='string'?nextContent:content;setSaving(true);try{const result=await api(`/projects/${projectId}/file`,{method:'PUT',body:JSON.stringify({path:selected,content:value})});setContent(value);setOriginal(value);setSaveResult(result);onManualSave(result)}catch(err){setSaveResult({saved:false,checks:{ok:false,errors:[err.message]}});throw err}finally{setSaving(false)}}
  const formatPython=async value=>(await api(`/projects/${projectId}/file/format`,{method:'POST',body:JSON.stringify({path:selected,content:value})})).content
  return <div className="code-view"><aside className="file-tree"><div className="tree-head"><span><FolderTree size={16}/>{t('projectFiles')}</span><small>{files.length}</small></div><label className="file-filter"><Search size={14}/><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder={t('filterFiles')}/></label><div className="tree-rows"><FileTreeRows node={tree} selected={selected} onSelect={setSelected} changedFiles={changedFiles} open={open} setOpen={setOpen}/></div></aside><React.Suspense fallback={<div className="editor-loading"><LoaderCircle className="spin" size={22}/></div>}><CodeEditor path={selected} value={content} revision={selectedRevision} onChange={setContent} onSave={save} onFormatPython={formatPython} saving={saving} saveResult={saveResult} dirty={content!==original} readOnly={readOnly}/></React.Suspense></div>
}

function ActivityPanel({ events }) { const {t}=useUi(); const rows=events.filter(e=>e.agent!=='user'); return <div className="activity-panel"><div className="activity-title"><SquareTerminal size={19}/><span>{t('agentActivity')}</span><small>{events.filter(e=>e.type==='tool').length} {t('toolCalls')}</small></div>{rows.map(event=>{const change=event.payload?.result?.change;return <div className="activity-line" key={event.id}><span className={`activity-icon ${event.type}`}>{event.type==='error'?<X size={14}/>:event.type==='tool'?<FileDiff size={14}/>:<Check size={14}/>}</span><div><b>{event.summary}</b><small>{agentMeta[event.agent]?.name||'System'} · {event.phase||event.type}{change&&` · +${change.added} −${change.removed}`}</small></div><time>{new Date(event.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div>})}</div> }

function BuilderPane({ project,events,files,changedFiles,fileRevision,onManualSave,readOnly,previewRevision }) {
  const {t}=useUi(); const [tab,setTab]=useState('preview'); const [device,setDevice]=useState('desktop'); const [key,setKey]=useState(0); const version=events.filter(e=>e.type==='completed').at(-1)?.payload?.version; useEffect(()=>{setKey(x=>x+1)},[previewRevision])
  return <section className="builder-pane"><div className="builder-tabs"><div><button className={tab==='preview'?'active':''} onClick={()=>setTab('preview')}><Eye size={17}/>{t('preview')}</button><button className={tab==='code'?'active':''} onClick={()=>setTab('code')}><Code2 size={17}/>{t('code')}{Object.keys(changedFiles).length>0&&<i className="live-dot"/>}</button><button className={tab==='activity'?'active':''} onClick={()=>setTab('activity')}><Activity size={17}/>{t('activity')}</button></div><div>{tab==='preview'&&<><button title={t('desktop')} className={device==='desktop'?'active icon-only':'icon-only'} onClick={()=>setDevice('desktop')}><Monitor size={17}/></button><button title={t('mobile')} className={device==='mobile'?'active icon-only':'icon-only'} onClick={()=>setDevice('mobile')}><Smartphone size={17}/></button><button title={t('refresh')} className="icon-only" onClick={()=>setKey(x=>x+1)}><RefreshCw size={17}/></button></>}</div></div><div className="builder-content">{tab==='preview'&&<div className={`preview-stage ${device}`}>{project.preview_ready||project.status==='preview_ready'?<div className="preview-frame"><div className="browser-bar"><i/><i/><i/><span>localhost / {project.name.toLowerCase().replaceAll(' ','-')}</span><Globe2 size={14}/></div><iframe title="Generated website preview" key={key} src={`/preview/${project.id}/`}/></div>:<div className="preview-empty"><div className="preview-pulse"><Code2 size={29}/></div><h3>{project.status==='awaiting_approval'?t('approvePreview'):t('previewSoon')}</h3><p>{t('previewDesc')}</p></div>}</div>}{tab==='code'&&<FileBrowser projectId={project.id} files={files} changedFiles={changedFiles} fileRevision={fileRevision} onManualSave={onManualSave} readOnly={readOnly}/>} {tab==='activity'&&<ActivityPanel events={events}/>}</div><div className="builder-footer"><span>{version?`Version ${version}`:t('unversioned')}</span><span className="footer-ready"><i/>{project.preview_ready?t('previewOnline'):t('localWorkspace')}</span></div></section>
}

function Workspace({ project,onProjectUpdate,onPublished }) {
  const {t}=useUi(); const [events,setEvents]=useState([]); const [runs,setRuns]=useState([]); const [files,setFiles]=useState([]); const [approving,setApproving]=useState(false); const [publishing,setPublishing]=useState(false); const [error,setError]=useState(''); const [fileRevision,setFileRevision]=useState(0); const [previewRevision,setPreviewRevision]=useState(0)
  const latestRun=runs.at(-1)||project.latest_run; const refreshFiles=useCallback(async()=>{const data=await api(`/projects/${project.id}/files`);setFiles(data.files)},[project.id]); const refresh=useCallback(async()=>{try{const [p,e,r,f]=await Promise.all([api(`/projects/${project.id}`),api(`/projects/${project.id}/events`),api(`/projects/${project.id}/runs`),api(`/projects/${project.id}/files`)]);onProjectUpdate(p);setEvents(e);setRuns(r);setFiles(f.files)}catch(err){setError(err.message)}},[project.id,onProjectUpdate])
  useEffect(()=>{refresh();const timer=setInterval(refresh,6000);return()=>clearInterval(timer)},[refresh])
  useEffect(()=>{if(!latestRun?.id||['preview_ready','failed','cancelled'].includes(latestRun.state))return;const token=localStorage.getItem('atoms_token');const source=new EventSource(`${API}/runs/${latestRun.id}/events/stream?token=${encodeURIComponent(token)}`);source.onmessage=event=>{const next=JSON.parse(event.data);setEvents(items=>items.some(x=>x.id===next.id)?items:[...items,next]);if(next.type==='tool'&&['write_file','replace_text'].includes(next.payload?.tool)){refreshFiles();setFileRevision(x=>x+1)}};source.addEventListener('done',()=>{source.close();refresh();setPreviewRevision(x=>x+1)});source.onerror=()=>source.close();return()=>source.close()},[latestRun?.id,latestRun?.state,refresh,refreshFiles])
  const changedFiles=useMemo(()=>events.reduce((map,event)=>{const path=event.payload?.result?.path;if(event.type==='tool'&&path&&['write_file','replace_text'].includes(event.payload?.tool))map[path]={eventId:event.id,change:event.payload.result.change};return map},{}),[events])
  const approve=async()=>{setApproving(true);try{await api(`/runs/${latestRun.id}/approve`,{method:'POST'});await refresh()}catch(err){setError(err.message)}finally{setApproving(false)}}; const revise=async content=>{setApproving(true);try{await api(`/runs/${latestRun.id}/revise`,{method:'POST',body:JSON.stringify({content})});await refresh()}catch(err){setError(err.message)}finally{setApproving(false)}}; const send=async payload=>{try{await api(`/projects/${project.id}/messages`,{method:'POST',body:JSON.stringify(payload)});await refresh()}catch(err){setError(err.message);throw err}}; const changeMode=async mode=>{try{onProjectUpdate(await api(`/projects/${project.id}/mode`,{method:'PATCH',body:JSON.stringify({mode})}))}catch(err){setError(err.message)}}
  const download=async()=>{const token=localStorage.getItem('atoms_token');const response=await fetch(`${API}/projects/${project.id}/export`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok){setError(t('exportError'));return}const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${project.name}.zip`;a.click();URL.revokeObjectURL(url)}; const publish=async()=>{setPublishing(true);try{await api(`/projects/${project.id}/publish`,{method:'POST'});onPublished()}catch(err){setError(err.message)}finally{setPublishing(false)}}
  const disabled=['created','planning','awaiting_approval','building','testing'].includes(latestRun?.state)
  const conversationEvents=useMemo(()=>events.filter(event=>{
    if(event.type==='plan'||event.type==='handoff')return false
    if(['mike','emma','bob'].includes(event.agent)&&event.type==='stage')return false
    return event.type!=='tool'||['run_checks','finish','publish_project'].includes(event.payload?.tool)
  }),[events])
  return <main className="workspace"><header className="workspace-header"><div className="project-title"><ProjectIcon project={project} large/><div><h1>{project.name}</h1><span>{t('personalWorkspace')}</span></div></div><div className="header-actions"><StatusPill status={project.status}/><select value={project.mode} onChange={e=>changeMode(e.target.value)}><option value="team">{t('teamMode')}</option><option value="engineer">{t('engineerMode')}</option></select><button className="secondary-btn" onClick={download}><Download size={16}/>{t('export')}</button><button className="publish-btn" disabled={publishing} onClick={publish}>{publishing?<LoaderCircle className="spin" size={16}/>:<Rocket size={16}/>} {publishing?t('publishing'):t('publish')}</button></div></header>{error&&<div className="workspace-error">{error}<button onClick={()=>setError('')}><X size={15}/></button></div>}<div className="workspace-grid"><Conversation projectId={project.id} events={conversationEvents} run={latestRun} onApprove={approve} onRevise={revise} approving={approving} onSend={send}/><BuilderPane project={project} events={events} files={files} changedFiles={changedFiles} fileRevision={fileRevision} previewRevision={previewRevision} onManualSave={result=>{refreshFiles();if(result.preview_restarted)setPreviewRevision(x=>x+1)}} readOnly={disabled}/></div></main>
}

function App() {
  const {setLocale,setTheme,locale}=useUi(); const [user,setUser]=useState(null); const [loading,setLoading]=useState(true); const [projects,setProjects]=useState([]); const [selectedId,setSelectedId]=useState(null); const [modal,setModal]=useState(false); const [activePage,setActivePage]=useState('workspace'); const [template,setTemplate]=useState(null); const [preferences,setPreferences]=useState({default_mode:'team'})
  const loadProjects=useCallback(async()=>{const items=await api('/projects');setProjects(items);setSelectedId(current=>current||items[0]?.id||null)},[]); const applyPreferences=data=>{setPreferences(data);if(data.locale)setLocale(data.locale);if(data.theme)setTheme(data.theme)}
  useEffect(()=>{const init=async()=>{if(!localStorage.getItem('atoms_token')){setLoading(false);return}try{setUser(await api('/auth/me'));applyPreferences(await api('/settings'));await loadProjects()}catch{}finally{setLoading(false)}};init();const logout=()=>setUser(null);window.addEventListener('atoms-logout',logout);return()=>window.removeEventListener('atoms-logout',logout)},[loadProjects])
  useEffect(()=>{const changed=()=>loadProjects();window.addEventListener('atoms-projects-changed',changed);return()=>window.removeEventListener('atoms-projects-changed',changed)},[loadProjects])
  const loggedIn=async next=>{setUser(next);applyPreferences(await api('/settings'));await loadProjects()}; const logout=()=>{localStorage.removeItem('atoms_token');setUser(null);setProjects([])}; const selected=projects.find(p=>p.id===selectedId); const updateProject=useCallback(next=>setProjects(items=>items.map(item=>item.id===next.id?next:item)),[]); const openProject=id=>{setSelectedId(id);setActivePage('workspace')}; const openNew=(starter=null)=>{setTemplate(starter);setModal(true)}; const archiveProject=async project=>{if(!window.confirm(locale==='zh-CN'?`归档“${project.name}”？之后可在已归档项目中恢复。`:`Archive “${project.name}”? You can restore it from Archived projects.`))return;try{await api(`/projects/${project.id}/archive`,{method:'POST'});setProjects(items=>items.filter(item=>item.id!==project.id));if(selectedId===project.id){setSelectedId(null);setActivePage('projects')}}catch(err){window.alert(err.message)}}
  if(loading)return <div className="boot"><Logo/><LoaderCircle className="spin"/></div>; if(!user)return <Login onLogin={loggedIn}/>
  let content; if(activePage==='team')content=<TeamPage/>; else if(activePage==='cloud')content=<CloudPage/>; else if(activePage==='discover')content=<DiscoverPage onUseTemplate={openNew}/>; else if(activePage==='archived')content=<ArchivedPage/>; else if(activePage==='projects')content=<ProjectsPage projects={projects} onOpen={openProject} onNew={()=>openNew()}/>; else content=selected?<Workspace project={selected} onProjectUpdate={updateProject} onPublished={()=>setActivePage('cloud')}/>:<EmptyWorkspace onNew={()=>openNew()}/>
  return <div className="app-shell"><Sidebar user={user} projects={projects} selectedId={selectedId} activePage={activePage} onSelect={openProject} onNavigate={setActivePage} onNew={()=>openNew()} onArchive={archiveProject} onLogout={logout}/>{content}<NewProjectModal open={modal} template={template} defaultMode={preferences.default_mode} onClose={()=>{setModal(false);setTemplate(null)}} onCreated={project=>{setProjects(items=>[project,...items]);setSelectedId(project.id);setActivePage('workspace')}}/></div>
}

createRoot(document.getElementById('root')).render(<React.StrictMode><ErrorBoundary><UiProvider><App/></UiProvider></ErrorBoundary></React.StrictMode>)
